{
	int element_counter;
	char **elements;
	char *query_str;
	struct collect_query collect_query;
	int i;
	size_t length = 0;
	size_t used = 0;

	debug(LOG_DEBUG, " Getting query, separator is [%s].", separator);

	element_counter = MHD_get_connection_values(connection, MHD_GET_ARGUMENT_KIND, counter_iterator, NULL);
	if (element_counter < 0) {
		*query = safe_strdup("");
		return MHD_NO;
	}
	elements = calloc((size_t)element_counter, sizeof(char *));
	if (elements == NULL) {
		return MHD_NO;
	}
	collect_query.i = 0;
	collect_query.elements = elements;

	// Collect the arguments of the query string from MHD
	MHD_get_connection_values(connection, MHD_GET_ARGUMENT_KIND, collect_query_string, &collect_query);

	for (i = 0; i < element_counter; i++) {
		if (!elements[i])
			continue;
		length += strlen(elements[i]);

		if (i > 0) // q=foo&o=bar the '&' need also some space
			length++;
	}

	// don't miss the zero terminator
	if (*query == NULL) {
		for (i = 0; i < element_counter; i++) {
			free(elements[i]);
		}
		free(elements);
		return 0;
	}

	query_str = safe_calloc(QUERYMAXLEN);

	for (i = 0; i < element_counter; i++) {
		size_t elem_len;
		size_t remaining;

		if (!elements[i]) {
			continue;
		}

		debug(LOG_DEBUG, " element [%d] is [%s]", i, elements[i]);

		elem_len = strlen(elements[i]);
		remaining = (used < QUERYMAXLEN) ? (QUERYMAXLEN - used - 1) : 0;
		if (elem_len > remaining) {
			elem_len = remaining;
		}
		if (elem_len > 0) {
			memcpy(*query + used, elements[i], elem_len);
			used += elem_len;
		}
		*query[used] = '\0';

		if (i == 0) {
			// query_str is empty when i = 0 so safe to copy a single char into it
			strcpy(query_str, "?");
		} else {
			if (QUERYMAXLEN - strlen(query_str) > 1) {
				strncat(query_str, separator, QUERYMAXLEN - strlen(query_str) - 1);
			}
		}

		// note: query string will be truncated if too long
		if (QUERYMAXLEN - strlen(query_str) > elem_len) {
			strncat(query_str, *query, QUERYMAXLEN - strlen(query_str) - 1);
		} else {
			debug(LOG_WARNING, " Query string exceeds the maximum of %d bytes so has been truncated.", QUERYMAXLEN/2);
		}

		free(elements[i]);
	}

	debug(LOG_DEBUG, " query is [%s]", query_str);
	strncpy(*query, query_str, QUERYMAXLEN - 1);
	(*query)[QUERYMAXLEN - 1] = '\0';
	free(query_str);
	free(elements);
	return 0;
}"}

