static Fixed lsr_translate_scale(GF_LASeRCodec *lsr, u32 val)
{
	if (lsr->coord_bits == 0 || lsr->coord_bits > 32) {
		return 0;
	}
	if (lsr->coord_bits < 32 && (val >> (lsr->coord_bits - 1))) {
		s32 v = (s32)(val - ((u32)1 << lsr->coord_bits));
		return INT2FIX(v) / 256;
	} else {
		return INT2FIX((s32)val) / 256;
	}
}

