		if (fault & VM_FAULT_RETRY) {
			/* Clear FAULT_FLAG_ALLOW_RETRY to avoid any risk
			 * of starvation. */
			flags &= ~FAULT_FLAG_ALLOW_RETRY;
			up_read(&mm->mmap_sem);
			goto retry;
		}
	}
	/*
	 * The instruction that caused the program check will
	 * be repeated. Don't signal single step via SIGTRAP.
	 */
	clear_tsk_thread_flag(tsk, TIF_PER_TRAP);
	fault = 0;
out_up:
	up_read(&mm->mmap_sem);
out:
	return fault;
}", "explanation": "The retry path jumped back to the retry label while still holding mm->mmap_sem, causing a recursive read lock acquisition (deadlock/lock imbalance). The fix releases the mmap_sem with up_read() before jumping back to retry, so the lock is reacquired exactly once per attempt."}

